import {productImages} from './product-images.js';
import {categories,initialOffers,whatsapp} from './data.js';
import {storageKey,expireOffers,visibleClosed,matches,countdown,safeUrl,dateTime,localInput} from './model.js';
import {illustration} from './art.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
let memoryOnly=false,offers;
try{const stored=JSON.parse(localStorage.getItem(storageKey));offers=Array.isArray(stored)&&stored.every(o=>o.id&&o.title&&Number.isFinite(o.price))?stored:initialOffers();}catch{offers=initialOffers();memoryOnly=true;}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(offers));}catch{if(!memoryOnly)toast('Armazenamento indisponível: alterações só nesta sessão.');memoryOnly=true;}}
offers=expireOffers(offers);persist();
const filters={search:'',category:'Todas',store:'',type:'all'};
let sort='featured';
const labels={ended:'Oferta encerrada','coupon-ended':'Cupom encerrado',soldout:'Esgotado'};
const closeLabels={common:'Oferta encerrada',flash:'Oferta encerrada',coupon:'Cupom encerrado'};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function info(title,html){$('#info-title').textContent=title;$('#info-body').innerHTML=html;$('#info-dialog').showModal();}
$$('[data-whatsapp]').forEach(a=>a.href=whatsapp);$('#year').textContent=new Date().getFullYear();
$('#categories').innerHTML=categories.map((c,i)=>`<button data-category="${esc(c)}" aria-pressed="${i===0}">${esc(c)}</button>`).join('');
$('#form-category').innerHTML=categories.slice(1).map(c=>`<option>${esc(c)}</option>`).join('');
function card(o){const closed=o.status!=='active';const badge=closed?'':o.type==='flash'?'<span class="badge flash">ϟ Relâmpago · teste</span>':o.type==='coupon'?'<span class="badge coupon">◇ Cupom · teste</span>':o.featured?'<span class="badge">☆ Escolha da curadoria</span>':'';const image=safeUrl(o.image)||productImages[o.id];return `<article class="card ${closed?'closed':''}" data-offer-id="${esc(o.id)}"><div class="product-visual ${image?'has-image':''}">${image?`<img src="${esc(image)}" alt="${esc(o.title)}" loading="lazy" referrerpolicy="no-referrer">`:illustration(o.art)}${badge}<span class="image-note">${image?'':'Ilustração provisória'}</span>${closed?`<div class="closed-banner">${labels[o.status]||'Oferta encerrada'}</div>`:''}</div><div class="card-body"><div class="card-meta"><span class="store-label ${o.store==='Amazon'?'amazon':o.store==='Shopee'?'shopee':''}">${esc(o.store)}</span>${o.demo?'<span class="demo-label">DEMONSTRAÇÃO</span>':''}</div><h3>${esc(o.title)}</h3><p class="specs">${esc(o.specs||o.category)}</p><p class="price-label">${o.demo?'Preço fictício':'Preço informado'}</p><div class="price"><span>R$</span> ${money(o.price).replace(/R\$\s*/,'')}</div><p class="terms">${esc(o.terms)}</p><p class="shipping">♧ ${esc(o.shipping||'Consulte frete e condições na loja')}</p>${!closed&&o.endsAt?`<div class="clock-box"><div><span>Termina em</span><span class="clock" data-deadline="${esc(o.endsAt)}">${countdown(o.endsAt)}</span></div><small>${o.fictionalDeadline||o.demo?'Demonstração — prazo fictício · ':''}${dateTime(o.endsAt)} (Brasília)</small></div>`:''}${o.type==='coupon'?`<button class="coupon-copy" data-copy="${esc(o.id)}" ${closed?'disabled':''}>${esc(o.coupon)} ${closed?'':'⧉'}</button><p class="coupon-terms">${esc(o.couponTerms)}</p>`:''}<div class="card-bottom"><p class="verify">${o.checkedAt?'Última verificação: '+dateTime(o.checkedAt)+' (Brasília)':'Última verificação: pendente'}<br>Confirme as condições finais na loja.</p>${closed?`<button class="offer-button" disabled>${labels[o.status]||'Oferta encerrada'}</button>`:`<button class="offer-button" data-visit="${esc(o.id)}">${o.demo?'Ver demonstração':`Ver oferta no${o.store==='Amazon'||o.store==='Shopee'?'a':''} ${esc(o.store)}`} <span>↗</span></button>`}</div></div></article>`;}
function render(){let active=offers.filter(o=>o.status==='active'&&matches(o,filters));active.sort((a,b)=>sort==='price-asc'?a.price-b.price:sort==='price-desc'?b.price-a.price:sort==='name'?a.title.localeCompare(b.title,'pt-BR'):Number(b.featured)-Number(a.featured));$('#offers-grid').innerHTML=active.map(card).join('');$('#empty').hidden=active.length>0;$('#result-count').textContent=`${active.length} oferta${active.length===1?'':'s'} encontrada${active.length===1?'':'s'}`;const closed=visibleClosed(offers).filter(o=>matches(o,filters));$('#closed-section').hidden=!closed.length;$('#closed-grid').innerHTML=closed.map(card).join('');$$('[data-visit]').forEach(button=>{const o=offers.find(o=>o.id===button.dataset.visit);if(o.demo)return;const link=document.createElement('a');link.className=button.className;link.innerHTML=button.innerHTML;link.href=safeUrl(o.url)||'#';link.target='_blank';link.rel='sponsored noopener noreferrer';link.setAttribute('aria-label',`Ver oferta de ${o.title} na loja ${o.store} (abre em nova aba)`);button.replaceWith(link);});renderAdmin();}
function renderAdmin(){$('#admin-list').innerHTML=offers.map(o=>`<div class="admin-item"><div><h3>${esc(o.title)}</h3><p>${money(o.price)} · ${esc(o.store)} · ${o.status==='active'?'Ativa':labels[o.status]}${o.demo?' · Demonstração':''}</p></div><div class="admin-item-actions"><button data-edit="${esc(o.id)}">Editar</button>${o.type==='flash'&&o.status==='active'?`<button data-expire="${esc(o.id)}">Expirar em 15 s</button>`:''}<button data-end="${esc(o.id)}" ${o.status!=='active'?'disabled':''}>Encerrar</button></div></div>`).join('');}
$('#search').addEventListener('input',e=>{filters.search=e.target.value.trim();render();});$('#store').addEventListener('change',e=>{filters.store=e.target.value;render();});$('#sort').addEventListener('change',e=>{sort=e.target.value;render();});
$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;filters.category=b.dataset.category;$$('[data-category]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();});
$('#type-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-type]');if(!b)return;filters.type=b.dataset.type;$$('[data-type]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();});
$('#clear-filters').onclick=()=>{Object.assign(filters,{search:'',category:'Todas',store:'',type:'all'});$('#search').value='';$('#store').value='';$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category==='Todas'));$$('[data-type]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.type==='all'));render();};
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#open-admin').onclick=()=>{renderAdmin();$('#admin-dialog').showModal();};
$('#about-test').onclick=()=>info('Uma prévia para experimentar','<p>Este é um protótipo local do TechInTudo Ofertas. Os 11 produtos e links foram fornecidos pela curadoria; preços, parcelamentos e frete ainda não foram verificados na loja.</p><p>As artes dos produtos foram fornecidas pela curadoria. Os prazos de relâmpago são fictícios, fixados no primeiro acesso e salvos neste navegador. Os cupons demonstrativos não são válidos para compras.</p><p>O painel não possui login nem banco de dados. Alterações ficam neste navegador. Antes da operação real, precisamos conectar autenticação e armazenamento, conferir os dados e as regras de cada programa de afiliados.</p>');
function openEdit(id){const form=$('#offer-form');form.reset();$('#form-error').textContent='';const o=offers.find(x=>x.id===id);$('#edit-title').textContent=o?'Editar oferta':'Cadastrar oferta';for(const name of ['id','title','price','store','url','terms','shipping','category','type','coupon','couponTerms','image','status'])if(o)form.elements[name].value=o[name]??'';form.elements.endsAt.value=o?localInput(o.endsAt):'';form.elements.featured.checked=!!o?.featured;form.elements.demo.checked=o?!!o.demo:true;if(!o){form.elements.shipping.value='Consulte frete e condições na loja';}updateForm();$('#edit-dialog').showModal();}
function updateForm(){const type=$('#offer-form').elements.type.value;$('#deadline-label').hidden=type==='common';$('#offer-form').elements.endsAt.required=type!=='common';$('#coupon-fields').hidden=type!=='coupon';$('#offer-form').elements.coupon.required=type==='coupon';$('#offer-form').elements.couponTerms.required=type==='coupon';}
$('#offer-form').elements.type.onchange=updateForm;$('#new-offer').onclick=()=>openEdit();
$('#offer-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements,old=offers.find(o=>o.id===f.id.value);const url=safeUrl(f.url.value),image=f.image.value?safeUrl(f.image.value):'';if(!url||image===null){$('#form-error').textContent='Use links HTTPS válidos, sem usuário ou senha.';return;}const deadline=f.type.value==='common'?null:new Date(f.endsAt.value+':00-03:00').toISOString();const status=f.status.value;if(deadline&&status==='active'&&new Date(deadline).getTime()<=Date.now()){$('#form-error').textContent='Para uma oferta ativa, informe um término no futuro (Brasília).';return;}const o={...old,id:old?.id||crypto.randomUUID(),title:f.title.value.trim(),price:Number(f.price.value),store:f.store.value,url,terms:f.terms.value.trim(),shipping:f.shipping.value.trim(),category:f.category.value,type:f.type.value,endsAt:deadline,fictionalDeadline:!!deadline,coupon:f.coupon.value.trim(),couponTerms:f.couponTerms.value.trim(),image,featured:f.featured.checked,demo:f.demo.checked,status,art:old?.art||'generic',checkedAt:old?.checkedAt||null,specs:old?.specs||'',endedAt:status==='active'?null:old?.endedAt||new Date().toISOString()};if(!o.title){$('#form-error').textContent='Informe um nome para a oferta.';return;}offers=old?offers.map(x=>x.id===o.id?o:x):[o,...offers];persist();render();$('#edit-dialog').close();toast('Oferta salva no navegador de teste.');};
$('#admin-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)openEdit(b.dataset.edit);if(b.dataset.end){offers=offers.map(o=>o.id===b.dataset.end?{...o,status:o.type==='coupon'?'coupon-ended':'ended',endedAt:new Date().toISOString()}:o);persist();render();toast('Oferta encerrada. Ela ficará visível até o fim do dia.');}if(b.dataset.expire){offers=offers.map(o=>o.id===b.dataset.expire?{...o,endsAt:new Date(Date.now()+15000).toISOString(),fictionalDeadline:true}:o);persist();render();toast('Prazo de teste definido: 15 segundos.');}});
$('#demo-coupon').onclick=()=>{if(offers.some(o=>o.id==='demo-coupon')){openEdit('demo-coupon');return;}offers.unshift({id:'demo-coupon',title:'Exemplo de cupom — apenas para testar',price:99.90,terms:'Valor fictício. Não corresponde a um produto real.',shipping:'Exemplo sem frete ou estoque real',url:'https://www.amazon.com.br/',store:'Amazon',category:'Acessórios',type:'coupon',coupon:'TESTE10',couponTerms:'Cupom fictício: 10% em pedidos a partir de R$ 100, limitado a R$ 20. Não é válido em nenhuma loja.',endsAt:new Date(Date.now()+3600000).toISOString(),fictionalDeadline:true,featured:false,demo:true,status:'active',checkedAt:null,endedAt:null,art:'generic',image:''});persist();render();toast('Cupom demonstrativo adicionado.');};
$('#reset-demo').onclick=()=>{info('Restaurar o teste?','<p>Esta ação substitui as alterações locais pelas 11 ofertas iniciais e cria novos prazos fictícios. Use apenas quando quiser reiniciar os testes.</p><button id="confirm-reset" class="button navy">Restaurar agora</button>');$('#confirm-reset').onclick=()=>{offers=initialOffers();persist();render();$('#info-dialog').close();toast('Versão inicial restaurada.');};};
document.addEventListener('click',async e=>{const visit=e.target.closest('[data-visit]');if(visit){const o=offers.find(x=>x.id===visit.dataset.visit);if(!o||o.status!=='active')return;if(o.demo){info('Oferta demonstrativa','<p>Este cartão serve apenas para testar o layout. Não há oferta real ou cupom válido associado.</p>');return;}info('Você vai para '+o.store,`<p><strong>${esc(o.title)}</strong></p><p>Preço informado: ${money(o.price)}. Ainda não verificado na loja. Confira preço, parcelamento, vendedor e frete antes de comprar.</p><p>Este é um link de afiliado e podemos receber comissão pela compra.</p><a class="button lime" href="${esc(safeUrl(o.url)||'#')}" target="_blank" rel="sponsored noopener noreferrer">Continuar para ${esc(o.store)} ↗</a>`);}const copy=e.target.closest('[data-copy]');if(copy){const o=offers.find(x=>x.id===copy.dataset.copy);if(o?.status!=='active')return;try{await navigator.clipboard.writeText(o.coupon);toast('Código copiado — cupom fictício, sem validade na loja.');}catch{toast('Código demonstrativo: '+o.coupon);}}});
function tick(){const next=expireOffers(offers);if(next.some((o,i)=>o!==offers[i])){offers=next;persist();render();}$$('[data-deadline]').forEach(el=>el.textContent=countdown(el.dataset.deadline));const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date());if(tick.day&&tick.day!==day)render();tick.day=day;}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
window.addEventListener('storage',e=>{if(e.key===storageKey){try{const next=JSON.parse(e.newValue);if(Array.isArray(next)){offers=expireOffers(next);render();}}catch{}}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.closest('.product-visual')){const el=e.target;el.replaceWith(Object.assign(document.createElement('span'),{textContent:'Imagem indisponível'}));}},true);
render();setInterval(tick,1000);
